<?php

declare(strict_types=1);

namespace Convaincre\Connect;

use DomainException;

final class Form
{
    public static function register(): void
    {
        Shortcodes::register();
        add_action('admin_post_nopriv_convaincre_connect_submit', [self::class, 'handle']);
        add_action('admin_post_convaincre_connect_submit', [self::class, 'handle']);
    }

    /** Allow only the normal post markup and the controls generated by our renderer. */
    public static function allowedMarkup(): array
    {
        $tags = wp_kses_allowed_html('post');
        $global = ['class'=>true, 'id'=>true, 'style'=>true, 'title'=>true, 'hidden'=>true, 'tabindex'=>true, 'role'=>true, 'aria-*'=>true, 'data-*'=>true];
        $controls = [
            'form'=>['action'=>true,'method'=>true],
            'input'=>array_fill_keys(['type','name','value','required','disabled','checked','maxlength','min','max','step','placeholder','autocomplete','inputmode'], true),
            'select'=>array_fill_keys(['name','required','disabled','multiple'], true),
            'option'=>array_fill_keys(['value','selected','disabled'], true),
            'textarea'=>array_fill_keys(['name','required','disabled','maxlength','rows','placeholder'], true),
            'button'=>array_fill_keys(['type','name','value','disabled'], true),
            'label'=>['for'=>true], 'fieldset'=>['disabled'=>true], 'legend'=>[],
            'progress'=>['value'=>true,'max'=>true], 'noscript'=>[], 'details'=>['open'=>true], 'summary'=>[],
            'time'=>['datetime'=>true], 'section'=>[], 'article'=>[], 'nav'=>[], 'div'=>[], 'p'=>[], 'span'=>[], 'small'=>[],
        ];
        foreach ($controls as $tag=>$attributes) {
            $tags[$tag] = array_merge($tags[$tag] ?? [], $global, $attributes);
        }
        return $tags;
    }

    public static function shortcode(array $attributes): string
    {
        return self::renderShortcode($attributes, null, 'convaincre_form');
    }

    public static function shortcodeForModule(
        array $attributes,
        string $expectedModule,
        string $tag
    ): string {
        return self::renderShortcode($attributes, $expectedModule, $tag);
    }

    private static function renderShortcode(
        array $attributes,
        ?string $expectedModule,
        string $tag
    ): string {
        $attributes = shortcode_atts(['id' => ''], $attributes, $tag);
        $externalId = substr(sanitize_text_field((string) $attributes['id']), 0, 120);
        $binding = Manifest::bindingByExternalId($externalId);
        if (
            $binding === null
            || (
                $expectedModule !== null
                && ! hash_equals(
                    $expectedModule,
                    (string) ($binding['module'] ?? '')
                )
            )
        ) {
            self::enqueueAssets();
            return '<div class="convaincre-connect-message convaincre-connect-message--error">'
                . esc_html__('Ce formulaire est momentanément indisponible.', 'campagne-convaincre')
                . '</div>';
        }

        self::enqueueAssets();

        $module = sanitize_key((string) ($binding['module'] ?? 'contact'));
        $token = FormToken::issue(
            self::tokenSecret(),
            (string) $binding['binding_key'],
            (int) $binding['version']
        );
        $action = esc_url(admin_url('admin-post.php'));
        $schema = is_array($binding['field_schema'] ?? null) ? $binding['field_schema'] : [];
        $presentation = self::presentation($schema);
        $title = self::presentationText(
            $presentation,
            'title',
            trim((string) ($binding['name'] ?? ''))
        );
        $eyebrow = self::presentationText(
            $presentation,
            'eyebrow',
            self::moduleLabel($module)
        );
        $intro = self::presentationText(
            $presentation,
            'intro',
            self::moduleIntro($module)
        );

        $appearance = Appearance::css(Appearance::forForm($externalId));
        $html = '<section class="convaincre-connect-widget convaincre-connect-widget--' . esc_attr($module)
            . ($appearance !== '' ? ' convaincre-connect-widget--styled" style="' . esc_attr($appearance) : '') . '">';
        $html .= self::statusMessage($presentation);
        if ($module === 'questionnaire' && ! empty($binding['aggregate_only'])) {
            $html .= '<p class="convaincre-connect-message" role="note">' . esc_html__('Ce questionnaire ne demande aucune coordonnée. Convaincre conserve des totaux et une preuve technique de transmission, sans fiche de contact. Le site peut conserver des journaux techniques.', 'campagne-convaincre') . '</p>';
        } elseif ($module === 'questionnaire') {
            $html .= '<p class="convaincre-connect-message" role="note">' . esc_html__('Ce questionnaire n’est pas anonyme. Vos réponses peuvent être associées à une fiche de contact. Ne renseignez pas de données personnelles concernant d’autres personnes dans les réponses libres.', 'campagne-convaincre') . '</p>';
        }
        if ($eyebrow !== '' || $title !== '' || $intro !== '') {
            $html .= '<div class="convaincre-connect-widget__header">';
            if ($eyebrow !== '') {
                $html .= '<span class="convaincre-connect-widget__eyebrow">' . esc_html($eyebrow) . '</span>';
            }
            if ($title !== '') {
                $html .= '<h2 class="convaincre-connect-widget__title">' . esc_html($title) . '</h2>';
            }
            if ($intro !== '') {
                $html .= '<p class="convaincre-connect-widget__intro">' . esc_html($intro) . '</p>';
            }
            $html .= '</div>';
        }

        $html .= '<form class="convaincre-connect-form" method="post" action="' . $action . '">';
        $html .= '<input type="hidden" name="action" value="convaincre_connect_submit">';
        $html .= '<input type="hidden" name="form_token" value="' . esc_attr($token) . '">';
        $html .= '<input class="convaincre-connect-honeypot" type="text" name="website" value="" tabindex="-1" autocomplete="off" aria-hidden="true">';

        $territoryMode = (string) ($binding['territory_mode'] ?? 'fixed');
        $municipalities = is_array($binding['municipalities'] ?? null)
            ? $binding['municipalities']
            : [];

        $hasConditions = false;
        foreach ($schema['questions'] ?? [] as $question) {
            if (! empty($question['show_if'])) {
                $hasConditions = true;
                break;
            }
        }
        $pageSize = ! empty($binding['aggregate_only']) ? (int) ($presentation['questions_per_page'] ?? 0) : 0;
        $pageSize = max(0, min(10, $pageSize));
        $answerCount = count($schema['answers'] ?? []);
        $multipage = $pageSize > 0 && $answerCount > $pageSize;
        if ($hasConditions || $multipage) {
            wp_enqueue_script('convaincre-connect-conditions', CONVAINCRE_CONNECT_URL . 'assets/conditions.js', [], CONVAINCRE_CONNECT_VERSION, true);
        }
        if ($multipage) {
            /* translators: %1$d: current questionnaire step; %2$d: total steps. */
            $html .= '<div class="convaincre-connect-steps" data-cc-steps hidden><p data-cc-step-label data-cc-label="' . esc_attr__('Étape %1$d sur %2$d', 'campagne-convaincre') . '" role="status" aria-live="polite"></p><progress data-cc-progress max="100" value="0" aria-label="' . esc_attr__('Progression du questionnaire', 'campagne-convaincre') . '"></progress></div>';
        }
        if ($hasConditions) {
            $html .= '<noscript><p>' . esc_html__('JavaScript est nécessaire pour ce questionnaire conditionnel.', 'campagne-convaincre') . '</p></noscript>';
        }
        $html .= '<div class="convaincre-connect-form__grid">';
        foreach ($schema['contact'] ?? [] as $field) {
            $required = in_array($field, $schema['required_contact'] ?? [], true);
            if ((string) $field === 'municipality_code' && $territoryMode === 'declared_address') {
                $html .= self::municipalityField($municipalities, $required, $presentation);
                continue;
            }
            $html .= self::contactField((string) $field, $required, $presentation);
        }
        $answerIndex = 0;
        foreach ($schema['answers'] ?? [] as $field) {
            if ($multipage && $answerIndex % $pageSize === 0) {
                $html .= '<section class="convaincre-connect-step" data-cc-page tabindex="-1">';
            }
            $question = self::questionForField($schema, (string) $field);
            $required = $question !== null
                ? ! empty($question['required'])
                : in_array($field, $schema['required_answers'] ?? [], true);
            $condition = $question['show_if'] ?? null;
            if (is_array($condition)) {
                $html .= '<fieldset class="convaincre-connect-conditional" data-cc-parent="' . esc_attr((string) $condition['question'])
                    . '" data-cc-value="' . esc_attr((string) $condition['value']) . '" hidden disabled>';
            }
            if ($multipage) {
                $html .= '<div class="convaincre-connect-step__question" data-cc-question' . ($required && ($question['type'] ?? '') === 'multiple' ? ' data-cc-required-multiple="' . esc_attr__('Sélectionnez au moins une réponse.', 'campagne-convaincre') . '"' : '') . '>';
            }
            $html .= self::answerField((string) $field, $required, $question, $presentation);
            if ($multipage) {
                $html .= '</div>';
            }
            if (is_array($condition)) {
                $html .= '</fieldset>';
            }
            ++$answerIndex;
            if ($multipage && ($answerIndex % $pageSize === 0 || $answerIndex === $answerCount)) {
                $html .= '</section>';
            }
        }
        $html .= '</div>';

        $consents = is_array($binding['consent_schema'] ?? null)
            ? $binding['consent_schema']
            : [];
        if ($consents !== []) {
            $html .= '<div class="convaincre-connect-form__consents">';
            foreach ($consents as $index => $consent) {
                if (! is_array($consent)) {
                    continue;
                }
                $required = ! empty($consent['required']);
                $html .= '<label class="convaincre-connect-consent">';
                $html .= '<input type="checkbox" name="consents[' . (int) $index . ']" value="1"' . ($required ? ' required' : '') . '> ';
                $html .= '<span>' . wp_kses_post((string) ($consent['wording'] ?? '')) . '</span>';
                $html .= '</label>';
            }
            $html .= '</div>';
        }

        $submitLabel = self::presentationText(
            $presentation,
            'submit_label',
            self::submitLabel($module)
        );
        $privacy = self::presentationText(
            $presentation,
            'privacy_text',
            __('Vos informations sont transmises de manière sécurisée à l’équipe à l’origine de ce formulaire.', 'campagne-convaincre')
        );
        $html .= '<div class="convaincre-connect-form__footer">';
        if ($multipage) {
            $html .= '<div class="convaincre-connect-steps__navigation" data-cc-navigation hidden>';
            $html .= '<button type="button" data-cc-prev>' . esc_html__('Précédent', 'campagne-convaincre') . '</button>';
            $html .= '<button type="button" data-cc-next>' . esc_html__('Suivant', 'campagne-convaincre') . '</button></div>';
        }
        $html .= '<button class="convaincre-connect-submit" type="submit"' . ($hasConditions ? ' data-cc-conditional-submit disabled' : '') . '>' . esc_html($submitLabel !== '' ? $submitLabel : __('Envoyer', 'campagne-convaincre')) . '</button>';
        if ($privacy !== '') {
            $html .= '<small class="convaincre-connect-form__privacy">' . esc_html($privacy) . '</small>';
        }
        $html .= '</div>';
        $html .= '</form>';
        $html .= '</section>';

        return $html;
    }

    public static function handle(): void
    {
        $redirect = self::redirectUrl();
        if (! empty($_POST['website'])) {
            self::redirect($redirect, 'accepted');
        }
        if (! self::rateLimit()) {
            self::redirect($redirect, 'rate_limited');
        }

        $token = isset($_POST['form_token'])
            ? sanitize_text_field(wp_unslash((string) $_POST['form_token']))
            : '';
        $tokenData = FormToken::verify(self::tokenSecret(), $token);
        if ($tokenData === null) {
            self::redirect($redirect, 'expired');
        }
        $binding = Manifest::bindingByKey((string) $tokenData['b']);
        if ($binding === null || (int) $binding['version'] !== (int) $tokenData['v']) {
            self::redirect($redirect, 'outdated');
        }

        try {
            $raw = [
                'contact' => self::unslashArray($_POST['contact'] ?? []),
                'answers' => self::unslashArray($_POST['answers'] ?? []),
                'consents' => self::unslashArray($_POST['consents'] ?? []),
            ];
            $payload = Payload::build(
                $binding,
                $raw,
                'wp-' . get_current_blog_id() . '-' . wp_generate_uuid4(),
                gmdate('c')
            );
            Queue::enqueue($payload);
            $result = Queue::process(1);
            self::redirect($redirect, $result['sent'] > 0 ? 'accepted' : 'queued');
        } catch (DomainException $exception) {
            self::redirect($redirect, sanitize_key($exception->getMessage()));
        } catch (\Throwable) {
            self::redirect($redirect, 'local_error');
        }
    }

    private static function enqueueAssets(): void
    {
        wp_enqueue_style(
            'convaincre-connect-forms',
            CONVAINCRE_CONNECT_URL . 'assets/forms.css',
            [],
            CONVAINCRE_CONNECT_VERSION
        );
    }

    private static function presentation(array $schema): array
    {
        return is_array($schema['presentation'] ?? null) ? $schema['presentation'] : [];
    }

    private static function presentationText(array $presentation, string $key, string $fallback): string
    {
        if (! array_key_exists($key, $presentation)) {
            return $fallback;
        }
        return trim((string) $presentation[$key]);
    }

    private static function fieldPresentationText(
        array $presentation,
        string $group,
        string $field,
        string $fallback = ''
    ): string {
        $values = is_array($presentation[$group] ?? null) ? $presentation[$group] : [];
        if (! array_key_exists($field, $values)) {
            return $fallback;
        }
        return trim((string) $values[$field]);
    }

    private static function statusMessage(array $presentation = []): string
    {
        $status = isset($_GET['convaincre_connect'])
            ? sanitize_key(wp_unslash((string) $_GET['convaincre_connect']))
            : '';
        $messages = [
            'accepted' => [
                self::presentationText(
                    $presentation,
                    'success_message',
                    __('Merci, votre réponse a bien été transmise.', 'campagne-convaincre')
                ),
                'success',
            ],
            'queued' => [
                self::presentationText(
                    $presentation,
                    'queued_message',
                    __('Merci, votre réponse est enregistrée et sera transmise automatiquement.', 'campagne-convaincre')
                ),
                'success',
            ],
            'rate_limited' => [__('Trop de tentatives. Merci de réessayer dans une minute.', 'campagne-convaincre'), 'warning'],
            'expired' => [__('Le formulaire a expiré. Rechargez la page puis réessayez.', 'campagne-convaincre'), 'warning'],
            'outdated' => [__('Le formulaire vient d’être mis à jour. Rechargez la page.', 'campagne-convaincre'), 'warning'],
            'required_contact_missing' => [__('Un champ obligatoire manque.', 'campagne-convaincre'), 'error'],
            'required_answer_missing' => [__('Une réponse obligatoire manque.', 'campagne-convaincre'), 'error'],
            'required_consent_missing' => [__('Un consentement obligatoire manque.', 'campagne-convaincre'), 'error'],
            'local_error' => [__('La réponse n’a pas pu être enregistrée. Merci de réessayer.', 'campagne-convaincre'), 'error'],
        ];
        if (! isset($messages[$status])) {
            return '';
        }
        [$message, $kind] = $messages[$status];
        if ($message === '') {
            return '';
        }
        return '<div class="convaincre-connect-message convaincre-connect-message--' . esc_attr($kind) . '" role="status">'
            . esc_html($message)
            . '</div>';
    }

    private static function contactField(string $field, bool $required, array $presentation = []): string
    {
        $types = [
            'email' => 'email',
            'phone' => 'tel',
            'address' => 'text',
            'postal_code' => 'text',
            'municipality_code' => 'text',
            'first_name' => 'text',
            'last_name' => 'text',
        ];
        $autocomplete = [
            'email' => 'email',
            'phone' => 'tel',
            'address' => 'street-address',
            'postal_code' => 'postal-code',
            'first_name' => 'given-name',
            'last_name' => 'family-name',
        ];
        $inputModes = [
            'email' => 'email',
            'phone' => 'tel',
            'postal_code' => 'numeric',
        ];
        $label = self::fieldPresentationText(
            $presentation,
            'field_labels',
            $field,
            self::label($field)
        );
        $placeholder = self::fieldPresentationText(
            $presentation,
            'field_placeholders',
            $field
        );
        $autocompleteAttribute = isset($autocomplete[$field])
            ? ' autocomplete="' . esc_attr($autocomplete[$field]) . '"'
            : '';
        $inputModeAttribute = isset($inputModes[$field])
            ? ' inputmode="' . esc_attr($inputModes[$field]) . '"'
            : '';
        $placeholderAttribute = $placeholder !== ''
            ? ' placeholder="' . esc_attr($placeholder) . '"'
            : '';
        $requiredMark = $required
            ? '<span class="convaincre-connect-required" aria-hidden="true">*</span>'
            : '';
        $modifier = in_array($field, ['first_name', 'last_name', 'postal_code', 'municipality_code'], true)
            ? ' convaincre-connect-field--half'
            : '';

        return '<label class="convaincre-connect-field' . $modifier . '">'
            . '<span class="convaincre-connect-field__label">' . esc_html($label) . $requiredMark . '</span>'
            . '<input type="' . esc_attr($types[$field] ?? 'text') . '" name="contact[' . esc_attr($field) . ']" maxlength="1000"'
            . $autocompleteAttribute
            . $inputModeAttribute
            . $placeholderAttribute
            . ($required ? ' required aria-required="true"' : '')
            . '>'
            . '</label>';
    }

    private static function municipalityField(array $municipalities, bool $required, array $presentation = []): string
    {
        $valid = [];
        foreach ($municipalities as $municipality) {
            if (! is_array($municipality)) {
                continue;
            }
            $code = sanitize_text_field((string) ($municipality['code'] ?? ''));
            $name = sanitize_text_field((string) ($municipality['name'] ?? ''));
            if ($code === '' || $name === '') {
                continue;
            }
            $valid[] = ['code' => $code, 'name' => $name];
        }

        if (count($valid) === 1) {
            return '<input type="hidden" name="contact[municipality_code]" value="'
                . esc_attr($valid[0]['code'])
                . '">';
        }

        $requiredMark = $required
            ? '<span class="convaincre-connect-required" aria-hidden="true">*</span>'
            : '';
        $label = self::fieldPresentationText(
            $presentation,
            'field_labels',
            'municipality_code',
            __('Commune', 'campagne-convaincre')
        );
        $placeholder = self::presentationText(
            $presentation,
            'municipality_placeholder',
            __('Choisir ma commune', 'campagne-convaincre')
        );
        $html = '<label class="convaincre-connect-field convaincre-connect-field--half">';
        $html .= '<span class="convaincre-connect-field__label">' . esc_html($label) . $requiredMark . '</span>';
        $html .= '<select name="contact[municipality_code]"' . ($required ? ' required aria-required="true"' : '') . '>';
        $html .= '<option value="">' . esc_html($placeholder) . '</option>';
        foreach ($valid as $municipality) {
            $html .= '<option value="' . esc_attr($municipality['code']) . '">' . esc_html($municipality['name']) . '</option>';
        }
        $html .= '</select></label>';
        return $html;
    }

    private static function questionForField(array $schema, string $field): ?array
    {
        foreach ($schema['questions'] ?? [] as $question) {
            if (! is_array($question)) {
                continue;
            }
            if (hash_equals((string) ($question['key'] ?? ''), $field)) {
                return $question;
            }
        }
        return null;
    }

    private static function answerField(
        string $field,
        bool $required,
        ?array $question = null,
        array $presentation = []
    ): string {
        $placeholder = self::fieldPresentationText(
            $presentation,
            'field_placeholders',
            $field
        );
        $placeholderAttribute = $placeholder !== ''
            ? ' placeholder="' . esc_attr($placeholder) . '"'
            : '';

        if ($question === null) {
            $label = self::fieldPresentationText(
                $presentation,
                'field_labels',
                $field,
                self::label($field)
            );
            $requiredMark = $required
                ? '<span class="convaincre-connect-required" aria-hidden="true">*</span>'
                : '';
            return '<label class="convaincre-connect-field convaincre-connect-field--wide convaincre-connect-field--answer">'
                . '<span class="convaincre-connect-field__label">' . esc_html($label) . $requiredMark . '</span>'
                . '<textarea name="answers[' . esc_attr($field) . ']" maxlength="5000" rows="4"'
                . $placeholderAttribute
                . ($required ? ' required aria-required="true"' : '')
                . '></textarea>'
                . '</label>';
        }

        $label = trim((string) ($question['label'] ?? self::label($field)));
        $type = sanitize_key((string) ($question['type'] ?? 'textarea'));
        $requiredMark = $required
            ? '<span class="convaincre-connect-required" aria-hidden="true">*</span>'
            : '';
        $legend = '<span class="convaincre-connect-field__label">'
            . esc_html($label)
            . $requiredMark
            . '</span>';
        $name = 'answers[' . esc_attr($field) . ']';

        if ($type === 'text') {
            return '<label class="convaincre-connect-field convaincre-connect-field--wide convaincre-connect-question">'
                . $legend
                . '<input type="text" name="' . $name . '" maxlength="5000"'
                . $placeholderAttribute
                . ($required ? ' required aria-required="true"' : '')
                . '>'
                . '</label>';
        }

        if ($type === 'textarea') {
            return '<label class="convaincre-connect-field convaincre-connect-field--wide convaincre-connect-question">'
                . $legend
                . '<textarea name="' . $name . '" maxlength="5000" rows="4"'
                . $placeholderAttribute
                . ($required ? ' required aria-required="true"' : '')
                . '></textarea>'
                . '</label>';
        }

        if ($type === 'scale') {
            $minimum = max(0, min(10, (int) ($question['min'] ?? 1)));
            $maximum = max($minimum + 1, min(10, (int) ($question['max'] ?? 5)));
            $html = '<fieldset class="convaincre-connect-question convaincre-connect-question--scale">';
            $html .= '<legend>' . $legend . '</legend>';
            $html .= '<div class="convaincre-connect-question__scale">';
            for ($value = $minimum; $value <= $maximum; $value++) {
                $html .= '<label class="convaincre-connect-question__scale-option">';
                $html .= '<input type="radio" name="' . $name . '" value="' . (int) $value . '"'
                    . ($required ? ' required' : '') . '>';
                $html .= '<span>' . (int) $value . '</span>';
                $html .= '</label>';
            }
            $html .= '</div></fieldset>';
            return $html;
        }

        $options = is_array($question['options'] ?? null)
            ? $question['options']
            : [];
        if ($type === 'ranking') {
            $html = '<fieldset class="convaincre-connect-question convaincre-connect-question--ranking">';
            $html .= '<legend>' . $legend . '</legend>';
            $html .= '<p class="convaincre-connect-question__hint">'
                . esc_html__('Classez vos priorités, de la plus importante à la moins importante.', 'campagne-convaincre')
                . '</p>';
            $html .= '<div class="convaincre-connect-question__ranking">';
            $rankCount = min(count($options), 5);
            for ($rank = 1; $rank <= $rankCount; $rank++) {
                $html .= '<label class="convaincre-connect-question__rank">';
                /* translators: %d: priority rank, from 1 to 5. */
                $html .= '<span>' . sprintf(esc_html__('%dᵉ priorité', 'campagne-convaincre'), $rank) . '</span>';
                $html .= '<select name="' . $name . '[]"' . ($required && $rank === 1 ? ' required' : '') . '>';
                $html .= '<option value="">' . esc_html__('Choisir', 'campagne-convaincre') . '</option>';
                foreach ($options as $option) {
                    if (! is_array($option)) {
                        continue;
                    }
                    $value = sanitize_key((string) ($option['value'] ?? ''));
                    $optionLabel = trim((string) ($option['label'] ?? ''));
                    if ($value === '' || $optionLabel === '') {
                        continue;
                    }
                    $html .= '<option value="' . esc_attr($value) . '">' . esc_html($optionLabel) . '</option>';
                }
                $html .= '</select></label>';
            }
            $html .= '</div></fieldset>';
            return $html;
        }

        if ($type === 'single' || $type === 'multiple') {
            $html = '<fieldset class="convaincre-connect-question convaincre-connect-question--choices">';
            $html .= '<legend>' . $legend . '</legend>';
            $html .= '<div class="convaincre-connect-question__choices">';
            foreach ($options as $option) {
                if (! is_array($option)) {
                    continue;
                }
                $value = sanitize_key((string) ($option['value'] ?? ''));
                $optionLabel = trim((string) ($option['label'] ?? ''));
                if ($value === '' || $optionLabel === '') {
                    continue;
                }
                $inputType = $type === 'multiple' ? 'checkbox' : 'radio';
                $inputName = $type === 'multiple' ? $name . '[]' : $name;
                $html .= '<label class="convaincre-connect-question__choice">';
                $html .= '<input type="' . $inputType . '" name="' . $inputName . '" value="' . esc_attr($value) . '"'
                    . ($required && $type === 'single' ? ' required' : '') . '>';
                $html .= '<span>' . esc_html($optionLabel) . '</span>';
                $html .= '</label>';
            }
            $html .= '</div></fieldset>';
            return $html;
        }

        return '<label class="convaincre-connect-field convaincre-connect-field--wide convaincre-connect-question">'
            . $legend
            . '<textarea name="' . $name . '" maxlength="5000" rows="4"'
            . $placeholderAttribute
            . ($required ? ' required aria-required="true"' : '')
            . '></textarea>'
            . '</label>';
    }

