    private static function tokenSecret(): string
    {
        return wp_salt('nonce') . '|' . Settings::keyId() . '|' . get_current_blog_id();
    }

    private static function rateLimit(): bool
    {
        $address = isset($_SERVER['REMOTE_ADDR']) && is_string($_SERVER['REMOTE_ADDR']) ? sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])) : 'unknown';
        $key = 'cc_rate_' . substr(hash_hmac('sha256', $address, wp_salt('auth')), 0, 32);
        $count = (int) get_transient($key);
        if ($count >= 10) {
            return false;
        }
        set_transient($key, (string) ($count + 1), MINUTE_IN_SECONDS);
        return true;
    }

    private static function redirectUrl(): string
    {
        $referer = wp_get_referer();
        if (! is_string($referer) || $referer === '') {
            return home_url('/');
        }
        return wp_validate_redirect($referer, home_url('/'));
    }

    private static function redirect(string $url, string $status): never
    {
        wp_safe_redirect(add_query_arg('convaincre_connect', sanitize_key($status), $url));
        exit;
    }

    private static function unslashArray(mixed $value): array
    {
        return is_array($value) ? wp_unslash($value) : [];
    }
